import { useQueryClient } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { poolsQuery } from './poolsQuery';

/** Downloads the pools as CSV: one line per member, pools and members in the order added, a pool member as pool:<name>
 *  and the cut as shown (empty when none). The pools are re-read first, so the file holds what the store holds now. */
function ExportPools({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();

  const exportCsv = async () => {
    const pools = await queryClient.fetchQuery({ ...poolsQuery(sheetId), staleTime: 0 });
    downloadCsv('pools.csv', [
      ['pool', 'member', 'share', 'cut'],
      ...pools.flatMap((p) => p.members.map((m) => [p.name, m.pool === null ? m.name : `pool:${m.pool}`, m.share, m.cut])),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void exportCsv()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 6.81, Component: ExportPools });
import { useQuery } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import { useCapFor } from '../pools/poolsQuery';
import { personDue, ratesQuery } from '../rates/ratesQuery';
import { useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, peopleQuery } from './peopleQuery';

/** Downloads the people as CSV, in list order and retired people included, with the figures the screen shows. */
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const capFor = useCapFor(sheetId);

  const exportCsv = () => {
    downloadCsv('people.csv', [
      ['name', 'grade', 'retired-from', 'due-total'],
      ...people.map((p) => [p.name, gradeOn(p, today) ?? p.grade, p.retiredFrom ?? '', personDue(p, people, claims, rates, today, floor, late, capFor(p.id))]),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={exportCsv}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 11, Component: ExportPeople });
import { Fragment, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { ratesQuery } from '../rates/ratesQuery';
import { fiscalYear, useFiscalStartMonth, useFloor, useLate } from '../settings/settingsQuery';
import { useUser } from '../session/useUser';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodDue, periodOf, periodsKey, periodsQuery, personPeriodCarried, personPeriodDue } from './periodsQuery';
import type { Period } from './periodsQuery';

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const WHOLE = /^\d+$/;
const YEAR = /^\d{4}$/;

function ClaimPeriod({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  return <td data-testid="claim-period">{periodOf(periods, claim.dueBy)?.name ?? ''}</td>;
}

/** Two columns per period on the sheet: its due-total, headed by its name, and its carried figure. */
function PersonPeriodHeaders({ sheetId }: { sheetId: string }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <th>{p.name}</th>
          <th>{p.name} carried</th>
        </Fragment>
      ))}
    </>
  );
}

/** The person's due-total for each period on the sheet (live while it is open, fixed while it is closed or soft-closed), and
 *  their carried figure for it: the due of their earlier periods' claims still OPEN or PENDING at its end. */
function PersonPeriodDues({ sheetId, personId }: { sheetId: string; personId: number }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const person = people.find((p) => p.id === personId);
  if (!person) return null;
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <td data-testid={`person-period-${p.name}-due-total`}>{personPeriodDue(p, person, claims, people, rates, floor, late)}</td>
          <td data-testid={`person-period-${p.name}-carried`}>
            {personPeriodCarried(p, periods, person, claims, people, rates, floor, late)}
          </td>
        </Fragment>
      ))}
    </>
  );
}

/** A period's closed flag (yes, soft or no) and the buttons that close, soft-close and reopen it (each for the roles the settings' permission matrix allows: by default closing and soft-closing are a clerk's or a steward's, reopening a steward's). A refusal
 *  shows on the period until its next action. */
function PeriodClosed({
  sheetId,
  period,
  error,
  setError,
}: {
  sheetId: string;
  period: Period;
  error: string;
  setError: (error: string) => void;
}) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const once = useSubmitOnce();
  const close = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/close`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () => setError(`The period ${period.name} could not be closed: it is already closed, or your role is not allowed to close it.`),
  });
  const softClose = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/soft-close`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () =>
      setError(`The period ${period.name} could not be soft-closed: it is already closed, or your role is not allowed to close it.`),
  });
  const reopen = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/reopen`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () =>
      setError(`The period ${period.name} could not be reopened: it is not closed, or your role is not allowed to reopen it.`),
  });

  return (
    <td>
      <span data-testid="period-closed">{period.closed ? 'yes' : period.soft ? 'soft' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="period-close"
        disabled={close.isPending}
        onClick={() => {
          setError('');
          once(() => close.mutateAsync());
        }}
      >
        Close
      </button>{' '}
      <button
        type="button"
        data-testid="period-soft-close"
        disabled={softClose.isPending}
        onClick={() => {
          setError('');
          once(() => softClose.mutateAsync());
        }}
      >
        Soft close
      </button>{' '}
      <button
        type="button"
        data-testid="period-reopen"
        disabled={reopen.isPending}
        onClick={() => {
          setError('');
          once(() => reopen.mutateAsync());
        }}
      >
        Reopen
      </button>
      {error && <span data-testid="period-error">{error}</span>}
    </td>
  );
}

/** A period's locked flag (yes or no) and the buttons that lock and unlock it (a steward's only; a locked period cannot
 *  be reopened). A refusal shows on the period (in its closed cell) until its next action. */
function PeriodLocked({
  sheetId,
  period,
  setError,
}: {
  sheetId: string;
  period: Period;
  setError: (error: string) => void;
}) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const once = useSubmitOnce();
  const lock = useMutation({
    mutationFn: (action: 'lock' | 'unlock') =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/${action}`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: (_e, action) =>
      setError(`The period ${period.name} could not be ${action}ed: it already is, or only a steward may ${action} it.`),
  });

  return (
    <td>
      <span data-testid="period-locked">{period.locked ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="period-lock"
        disabled={lock.isPending}
        onClick={() => {
          setError('');
          once(() => lock.mutateAsync('lock'));
        }}
      >
        Lock
      </button>{' '}
      <button
        type="button"
        data-testid="period-unlock"
        disabled={lock.isPending}
        onClick={() => {
          setError('');
          once(() => lock.mutateAsync('unlock'));
        }}
      >
        Unlock
      </button>
    </td>
  );
}

/** A period's closed and locked cells, sharing the one error the row shows: any action on the period clears it. */
function PeriodState({ sheetId, period }: { sheetId: string; period: Period }) {
  const [error, setError] = useState('');
  return (
    <>
      <PeriodClosed sheetId={sheetId} period={period} error={error} setError={setError} />
      <PeriodLocked sheetId={sheetId} period={period} setError={setError} />
    </>
  );
}

/** The sheet's periods, each with its due-total — the figures of the counting claims due by a date in it, fixed
 *  while the period is closed or soft-closed and live again once it is reopened — and the form a period is added through. */
function Periods({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const periods = useQuery(periodsQuery(sheetId));
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const fiscalStart = useFiscalStartMonth(sheetId);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [cap, setCap] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: Pick<Period, 'name' | 'from' | 'to'> & { cap: string }) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setName('');
      setFrom('');
      setTo('');
      setCap('');
    },
    onError: () => setError('The period could not be added: its name must be new, its dates must not overlap another period and its cap must be a whole number of at least 1.'),
  });

  const list = periods.data ?? [];
  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const n = name.trim();
    const f = from.trim();
    const t = to.trim();
    const c = cap.trim();
    if (n === '') {
      setError('A period needs a name.');
      return;
    }
    if (!DATE.test(f) || !DATE.test(t)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (t < f) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    if (list.some((p) => p.name === n)) {
      setError(`There is already a period named ${n}.`);
      return;
    }
    const overlapped = list.find((p) => p.from <= t && f <= p.to);
    if (overlapped) {
      setError(`The period overlaps ${overlapped.name}.`);
      return;
    }
    if (c !== '' && (!WHOLE.test(c) || Number(c) < 1)) {
      setError('The claim cap must be a whole number of at least 1, or blank for none.');
      return;
    }
    once(() => add.mutateAsync({ name: n, from: f, to: t, cap: c }));
  };

  const dueTotal = (period: Period) => periodDue(period, claims, people, rates, floor, late);

  const edit = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <section data-testid="periods">
      <h3>Periods</h3>
      <form data-testid="period-form" onSubmit={submit}>
        <label>
          Name <input data-testid="period-form-name" value={name} onChange={edit(setName)} />
        </label>{' '}
        <label>
          From <input data-testid="period-form-from" type="date" value={from} onChange={edit(setFrom)} />
        </label>{' '}
        <label>
          To <input data-testid="period-form-to" type="date" value={to} onChange={edit(setTo)} />
        </label>{' '}
        <label>
          Claim cap <input data-testid="period-form-cap" inputMode="numeric" value={cap} onChange={edit(setCap)} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={add.isPending}>
          Add period
        </button>
        {error && <p data-testid="period-form-error">{error}</p>}
      </form>
      <GeneratePeriods sheetId={sheetId} />
      {periods.isError && <p data-testid="periods-load-error">Could not load the periods.</p>}
      <table data-testid="periods-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Fiscal year</th>
            <th>Due</th>
            <th>Claim cap</th>
            <th>Closed</th>
            <th>Locked</th>
          </tr>
        </thead>
        <tbody>
          {list.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-fy">{fiscalYear(p.from, fiscalStart)}</td>
              <td data-testid="period-due-total">{dueTotal(p)}</td>
              <td data-testid="period-cap">{p.cap ?? ''}</td>
              <PeriodState sheetId={sheetId} period={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

/** Makes a period per calendar month — or per month of the fiscal year typed, or per quarter of the year typed — from the from-date's month to the to-date's month (a blank date is the
 *  sheet's today), leaving out a month whose name is taken or whose days overlap a period, and shows how many
 *  were made. A to-date before the from-date is refused. */
function GeneratePeriods({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const today = useSheetToday(sheetId);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [year, setYear] = useState('');
  const [quartersYear, setQuartersYear] = useState('');
  const [error, setError] = useState('');
  const [made, setMade] = useState<number | undefined>();
  const once = useSubmitOnce();
  const generate = useMutation({
    mutationFn: (body: { from: string; to: string }) =>
      postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods/generate`, body, user),
    onSuccess: async (r) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setMade(r.made);
    },
    onError: () => setError('The periods could not be generated: the dates must be dates and the to-date on or after the from-date.'),
  });
  const generateFy = useMutation({
    mutationFn: (body: { year: string }) =>
      postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods/generate-fy`, body, user),
    onSuccess: async (r) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setMade(r.made);
    },
    onError: () => setError('The fiscal year could not be generated: the year must be a year (yyyy).'),
  });
  const generateQuarters = useMutation({
    mutationFn: (body: { year: string }) =>
      postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods/generate-quarters`, body, user),
    onSuccess: async (r) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setMade(r.made);
    },
    onError: () => setError('The quarters could not be generated: the year must be a year (yyyy).'),
  });

  // The fiscal year FY<yyyy> starts on the first of the sheet's fiscal start month in that year; its twelve
  // months are made as the generator makes them.
  const submitFy = () => {
    setError('');
    setMade(undefined);
    const y = year.trim();
    if (!YEAR.test(y)) {
      setError('The fiscal year must be a year (yyyy).');
      return;
    }
    once(() => generateFy.mutateAsync({ year: y }));
  };

  // The four calendar quarters of the year typed, named <yyyy>-Q1 to <yyyy>-Q4, each made as the period form
  // would add it.
  const submitQuarters = () => {
    setError('');
    setMade(undefined);
    const y = quartersYear.trim();
    if (!YEAR.test(y)) {
      setError('The year must be a year (yyyy).');
      return;
    }
    once(() => generateQuarters.mutateAsync({ year: y }));
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setMade(undefined);
    const f = from.trim() || today;
    const t = to.trim() || today;
    if (!DATE.test(f) || !DATE.test(t)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (t < f) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    once(() => generate.mutateAsync({ from: f, to: t }));
  };

  const edit = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <form data-testid="period-generate-form" onSubmit={submit}>
      <label>
        From <input data-testid="period-generate-from" type="date" value={from} onChange={edit(setFrom)} />
      </label>{' '}
