-- A sheet's periods: a name unique on the sheet and a from and to date, inclusive. No two periods
-- of a sheet overlap (checked when one is added).
CREATE TABLE period (
    sheet_id  VARCHAR(255) NOT NULL,
    name      VARCHAR(255) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date),
    PRIMARY KEY (sheet_id, name)
);
-- A period may cap how many OPEN or PENDING claims each person has in it (null: no cap). Opening a claim that belongs
-- to the period (its due-by falls in it) is refused once its person has that many. Kept in the period's history too
-- (see V40). The journal trigger is made again around the change, as in V65.
DROP TRIGGER period_journal;
ALTER TABLE period ADD COLUMN claim_cap INT;
ALTER TABLE period_history ADD COLUMN claim_cap INT;
CREATE TRIGGER period_journal AFTER INSERT, UPDATE, DELETE ON period FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
-- A period can be soft-closed: its due-total (closed_total) and its people's figures (period_person_total) are fixed,
-- but claims dated in it can still change. A claim added while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- A steward may lock a period, and unlock it again: a locked period cannot be reopened. Kept in the period's history
-- too (see V40). The journal trigger is made again around the change, as in V70.
DROP TRIGGER period_journal;
ALTER TABLE period ADD COLUMN locked BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period_history ADD COLUMN locked BOOLEAN;
CREATE TRIGGER period_journal AFTER INSERT, UPDATE, DELETE ON period FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
